INSERT OR IGNORE INTO games(id,title,description,platforms,genres,release_date,developer,publisher,cover_url,hero_url,steam_app_id,created_at) VALUES('stardew-valley','Stardew Valley','You''ve inherited your grandfather''s old farm plot in Stardew Valley. Armed with hand-me-down tools and a few coins, you set out to begin your new life. Can you learn to live off the land and turn these overgrown fields into a thriving home?','["PC","Mac","Linux","PS4","Xbox One","Switch","Android","iOS"]','["Simulation","RPG"]','2016-02-25','ConcernedApe','ConcernedApe','/images/stardew-valley.jpg','/images/stardew-valley-hero.jpg',413150,1793341027693);
